select mn.*,pre.p_name as pName,sys.c_name as cName,sys.c_id as cId from Final_Accounting_Approval mn left join pre_project pre on mn.p_id = pre.p_id left join sys_company sys on mn.faa_Approval_Unit = sys.c_id
mn.status=1
and mn.id = #{id}

select mn.*,pre.p_name as pName,sys.c_name as cName,sys.c_id as cId
from Final_Accounting_Approval mn
left join pre_project pre on mn.p_id = pre.p_id
left join sys_company sys on mn.faa_Approval_Unit = sys.c_id

    mn.status=1
    
        and mn.pId = #{request.pId}
    
    
        
            
                and likePname(#{request.pName},pre.P_Id)=true
            
            
                and likeCname(#{request.cName},sys.C_Id)=true
            
        
        
            
                and pre.P_Name like concat('%',#{request.pName},'%')
            
            
                and sys.c_name like concat('%',#{request.cName},'%')
            
        
    
    
        and mn.state = #{request.state}
    
    
        and mn.faa_Approval_Time = #{request.faaApprovalTime}
    
    
        and mn.faa_Approval_Unit = #{request.faaApprovalUnit}
    
    
        and mn.create_Uid = #{request.createUid}
    
    
        and mn.create_Time = #{request.createTime}
    
    
        and pre.P_Name in
        
            #{pName}
        
    
    
        and mn.state in
        
            #{state}
        
    
    
        and mn.faa_Approval_Investment in
        
            #{faaApprovalInvestment}
        
    
    
        and mn.create_Uname in
        
            #{createUname}
